        const delta = patch.linkText.length - (ref.end - ref.start)
        box.text = before + patch.linkText + after
        // Shift references that sit entirely after the edited range.
        for (const other of box.references!) {
          if (other.id !== ref.id && other.start >= ref.end) {
            other.start += delta
            other.end += delta
          }
        }
        ref.end = ref.start + patch.linkText.length
      }

      if (patch.targetPageId !== undefined) {
        ref.targetPageId = patch.targetPageId
      }

      box.references!.sort((a, b) => a.start - b.start)
      this.persist()
    },

    /** Remove a text box (used when it is emptied out). */
    removeTextBox(pageId: string, boxId: string) {
      const page = this.pages.find((p) => p.id === pageId)
      if (page?.boxes) {
        page.boxes = page.boxes.filter((b) => b.id !== boxId)
        this.persist()
      }
    },

    /** Delete a page and all of its descendants. */
    deletePage(id: string) {
      const toRemove = new Set<string>([id])
      let changed = true
      while (changed) {
        changed = false
        for (const p of this.pages) {
          if (p.parentId && toRemove.has(p.parentId) && !toRemove.has(p.id)) {
            toRemove.add(p.id)
            changed = true
          }
        }
      }
      this.pages = this.pages.filter((p) => !toRemove.has(p.id))
      this.persist()
    },

    /** Re-parent a page (e.g. drag & drop). Guards against cycles. */
    movePage(id: string, newParentId: string | null) {
      if (id === newParentId) return
      // Prevent moving a page under one of its own descendants.
      let cursor = newParentId
      while (cursor) {
        if (cursor === id) return
        cursor = this.pages.find((p) => p.id === cursor)?.parentId ?? null
      }
      const page = this.pages.find((p) => p.id === id)
      if (page) {
        page.parentId = newParentId
        this.persist()
      }
    },

    resetToSeed() {
      this.notebooks = structuredClone(seedNotebooks)
      this.pages = normalizePages(structuredClone(seedPages))
      this.persist()
    }
  }
})

import { defineStore } from 'pinia'
import { evaluateNotes } from '@/services/evaluationApi'
import { clearProgress, setLiveScores } from '@/utils/progress'
import { useNotesStore } from './notesStore'

interface State {
  /** True while an evaluation request is in flight. */
  loading: boolean
  /** Last error message, if the most recent evaluation failed. */
  error: string | null
  /** ISO timestamp of the last successful evaluation. */
  lastEvaluatedAt: string | null
}

/**
 * Optional convenience wrapper around backend evaluation. `AppLayout.vue`
 * currently drives evaluation inline, but this store offers the same behaviour
 * for components that prefer a shared, reactive loading/error state.
 */
export const useProgressStore = defineStore('progress', {
  state: (): State => ({
    loading: false,
    error: null,
    lastEvaluatedAt: null
  }),

  actions: {
    /**
     * Send notebooks + pages to the backend and merge the returned page and
     * notebook scores into the progress cache.
     *
     * @param notebookId Optional — evaluate only this notebook.
     */
    async evaluate(notebookId?: string) {
      const notes = useNotesStore()
      this.loading = true
      this.error = null
      try {
        // A single-notebook evaluation must not upload unrelated notebooks or
        // pages. Evaluate All intentionally keeps the complete dataset.
        const notebooks = notebookId
          ? notes.notebooks.filter((notebook) => notebook.id === notebookId)
          : notes.notebooks
        const pages = notebookId
          ? notes.pages.filter((page) => page.notebookId === notebookId)
          : notes.pages

        const { pageScores, notebookScores } = await evaluateNotes(
          notebooks,
          pages,
          notebookId
        )
        setLiveScores(pageScores)
        setLiveScores(notebookScores)
        this.lastEvaluatedAt = new Date().toISOString()
      } catch (e) {
        this.error = e instanceof Error ? e.message : String(e)
      } finally {
        this.loading = false
      }
    },

    /** Drop all cached scores (e.g. after resetting to seed data). */
    reset() {
      clearProgress()
      this.lastEvaluatedAt = null
      this.error = null
    }
  }
})

import { defineStore } from 'pinia'
import { evaluateNotes } from '@/services/evaluationApi'
import { clearProgress, setLiveScores } from '@/utils/progress'
import { useNotesStore } from './notesStore'

interface State {
  /** True while an evaluation request is in flight. */
  loading: boolean
  /** Last error message, if the most recent evaluation failed. */
  error: string | null
  /** ISO timestamp of the last successful evaluation. */
  lastEvaluatedAt: string | null
}

/**
 * Optional convenience wrapper around backend evaluation. `AppLayout.vue`
 * currently drives evaluation inline, but this store offers the same behaviour
 * for components that prefer a shared, reactive loading/error state.
 */
export const useProgressStore = defineStore('progress', {
  state: (): State => ({
    loading: false,
    error: null,
    lastEvaluatedAt: null
  }),

  actions: {
    /**
     * Send notebooks + pages to the backend and merge the returned page and
     * notebook scores into the progress cache.
     *
     * @param options.notebookId Optional — evaluate only this notebook.
     * @param options.pageId     Optional — evaluate only this single page. Takes
     *   precedence over `notebookId`; no other page (parent or sibling subpage)
     *   is scored, keeping the request cheap for large page trees.
     */
    async evaluate(options: { notebookId?: string; pageId?: string } = {}) {
      const { notebookId, pageId } = options
      const notes = useNotesStore()
      this.loading = true
      this.error = null
      try {
        // Only upload what is being evaluated. A single-page request sends just
        // that page; a notebook request sends that notebook's pages; "Evaluate
        // All" keeps the complete dataset.
        let notebooks = notes.notebooks
        let pages = notes.pages
        if (pageId) {
          const page = notes.pages.find((p) => p.id === pageId)
          pages = page ? [page] : []
          const owningId = notebookId ?? page?.notebookId
          notebooks = owningId
            ? notes.notebooks.filter((notebook) => notebook.id === owningId)
            : notes.notebooks
        } else if (notebookId) {
          notebooks = notes.notebooks.filter((notebook) => notebook.id === notebookId)
          pages = notes.pages.filter((page) => page.notebookId === notebookId)
        }

        const { pageScores, notebookScores } = await evaluateNotes(
          notebooks,
          pages,
          notebookId,
          pageId
        )
        setLiveScores(pageScores)
        setLiveScores(notebookScores)
        this.lastEvaluatedAt = new Date().toISOString()
      } catch (e) {
        this.error = e instanceof Error ? e.message : String(e)
      } finally {
        this.loading = false
      }
    },

    /** Drop all cached scores (e.g. after resetting to seed data). */
    reset() {
      clearProgress()
      this.lastEvaluatedAt = null
      this.error = null
    }
  }
})

import { describe, it, expect } from 'vitest'
import {
  DEFAULT_THRESHOLDS,
  progressLevel,
  getProgress
} from '@/utils/progress'

describe('progressLevel', () => {
  it('returns "danger" below the danger threshold (< 33)', () => {
    expect(progressLevel(0)).toBe('danger')
    expect(progressLevel(32)).toBe('danger')
  })

  it('returns "warn" between danger and warn thresholds (33–74)', () => {
    expect(progressLevel(33)).toBe('warn')
    expect(progressLevel(74)).toBe('warn')
  })

  it('returns "good" at/above the warn threshold (>= 75)', () => {
    expect(progressLevel(75)).toBe('good')
    expect(progressLevel(100)).toBe('good')
  })

  it('honours custom thresholds', () => {
    expect(progressLevel(50, { danger: 60, warn: 90 })).toBe('danger')
    expect(progressLevel(80, { danger: 60, warn: 90 })).toBe('warn')
    expect(progressLevel(95, { danger: 60, warn: 90 })).toBe('good')
  })

  it('exposes sensible defaults', () => {
    expect(DEFAULT_THRESHOLDS).toEqual({ danger: 33, warn: 75 })
  })
})

describe('getProgress', () => {
  it('is deterministic for the same id', () => {
    expect(getProgress('nb-1')).toBe(getProgress('nb-1'))
  })

  it('always returns a value within 0–100', () => {
    for (const id of ['a', 'nb-1', 'pg-xyz', 'longer-id-string']) {
      const v = getProgress(id)
      expect(v).toBeGreaterThanOrEqual(0)
      expect(v).toBeLessThanOrEqual(100)
    }
  })
})

import { describe, it, expect, beforeEach } from 'vitest'
import {
  DEFAULT_THRESHOLDS,
  progressLevel,
  getProgress,
  setProgress,
  setLiveScores,
  clearProgress,
  DEFAULT_PROGRESS
} from '@/utils/progress'

describe('progressLevel', () => {
  it('returns "danger" below the danger threshold (< 33)', () => {
    expect(progressLevel(0)).toBe('danger')
    expect(progressLevel(32)).toBe('danger')
  })

  it('returns "warn" between danger and warn thresholds (33–74)', () => {
    expect(progressLevel(33)).toBe('warn')
    expect(progressLevel(74)).toBe('warn')
  })

  it('returns "good" at/above the warn threshold (>= 75)', () => {
    expect(progressLevel(75)).toBe('good')
    expect(progressLevel(100)).toBe('good')
  })

  it('honours custom thresholds', () => {
    expect(progressLevel(50, { danger: 60, warn: 90 })).toBe('danger')
    expect(progressLevel(80, { danger: 60, warn: 90 })).toBe('warn')
    expect(progressLevel(95, { danger: 60, warn: 90 })).toBe('good')
  })

  it('exposes sensible defaults', () => {
    expect(DEFAULT_THRESHOLDS).toEqual({ danger: 33, warn: 75 })
  })
})

describe('getProgress', () => {
  beforeEach(() => {
    clearProgress()
  })

  it('returns the default for unknown ids', () => {
    expect(getProgress('nb-unknown')).toBe(DEFAULT_PROGRESS)
  })

  it('is deterministic for the same id', () => {
    expect(getProgress('nb-1')).toBe(getProgress('nb-1'))
  })

  it('always returns a value within 0–100', () => {
    for (const id of ['a', 'nb-1', 'pg-xyz', 'longer-id-string']) {
      const v = getProgress(id)
      expect(v).toBeGreaterThanOrEqual(0)
      expect(v).toBeLessThanOrEqual(100)
    }
  })

  it('reflects a value stored via setProgress (clamped + rounded)', () => {
    setProgress('nb-1', 73.6)
    expect(getProgress('nb-1')).toBe(74)
    setProgress('nb-1', 250)
    expect(getProgress('nb-1')).toBe(100)
    setProgress('nb-1', -10)
    expect(getProgress('nb-1')).toBe(0)
  })

  it('merges backend results via setLiveScores', () => {
    setLiveScores({
      'nb-work': { score: 62, understandingNotes: 'ok' },
      'pg-feynman': { score: 88, understandingNotes: 'clear explanation' }
    })
    expect(getProgress('nb-work')).toBe(62)
    expect(getProgress('pg-feynman')).toBe(88)
  })

  it('clearProgress resets the cache', () => {
    setProgress('nb-1', 50)
    clearProgress()
    expect(getProgress('nb-1')).toBe(DEFAULT_PROGRESS)
  })
})

/**
 * Progress model for notebooks and pages.
 *
 * ─────────────────────────────────────────────────────────────────────────
 * BACKEND SEAM
 * ─────────────────────────────────────────────────────────────────────────
 * Progress values are now provided by the Spring Boot backend, which asks an
 * LLM (or a deterministic offline heuristic) to grade how well each notebook /
 * page topic appears to be understood — following the Feynman technique.
 *
 * The backend result is cached in-module via `setProgress` / `setProgresses`
 * (populated by `useProgressStore`), so the widely-used `getProgress(id)`
 * accessor stays synchronous for templates.
 *
 * Color thresholds are centralized here so they can be made user-customizable
 * later without touching the components.
 */

export interface ProgressThresholds {
  /** Below this percent → "danger" (red). */
  danger: number
  /** Below this percent → "warn" (yellow); at/above → "good" (green). */
  warn: number
}

/** Default thresholds: red < 33, yellow < 75, green ≥ 75. */
export const DEFAULT_THRESHOLDS: ProgressThresholds = {
  danger: 33,
  warn: 75
}

export type ProgressLevel = 'danger' | 'warn' | 'good'

/**
 * Map a percent value to a color level using the given thresholds.
 */
export function progressLevel(
  value: number,
  thresholds: ProgressThresholds = DEFAULT_THRESHOLDS
): ProgressLevel {
  if (value < thresholds.danger) return 'danger'
  if (value < thresholds.warn) return 'warn'
  return 'good'
}

/**
 * In-memory cache of backend-evaluated scores, keyed by notebook / page id.
 * Populated by `useProgressStore.evaluate()` after calling the backend.
 */
const scoreCache: Record<string, number> = {}

/**
 * In-memory cache of the LLM's short "understanding notes" per id, shown as a
 * tooltip on the progress badge so users can see WHY a topic scored as it did.
 */
const notesCache: Record<string, string> = {}

/**
 * Fallback percent for ids the backend has not evaluated yet (e.g. a newly
 * created notebook/page, or before the first evaluation completes).
 */
export const DEFAULT_PROGRESS = 0

/** Clamp a raw value into the valid 0–100 progress range. */
function clamp(value: number): number {
  if (Number.isNaN(value)) return DEFAULT_PROGRESS
  return Math.max(0, Math.min(100, Math.round(value)))
}

/** Store a single backend-evaluated score. */
export function setProgress(id: string, value: number): void {
  scoreCache[id] = clamp(value)
}

/** Bulk-store backend-evaluated scores (id → percent). */
export function setProgresses(scores: Record<string, number>): void {
  for (const [id, value] of Object.entries(scores)) {
    scoreCache[id] = clamp(value)
  }
}

/**
 * Merge backend evaluation results into the progress cache.
 *
 * Accepts the `{ score, understandingNotes }` shape returned by the backend
 * (see `evaluationApi.ts`), so callers can pass `pageScores` / `notebookScores`
 * directly.
 */
export function setLiveScores(
  scores: Record<string, { score: number; understandingNotes?: string }>
): void {
  for (const [id, entry] of Object.entries(scores)) {
    if (entry && typeof entry.score === 'number') {
      scoreCache[id] = clamp(entry.score)
      if (entry.understandingNotes) {
        notesCache[id] = entry.understandingNotes
      }
    }
  }
}

/** Clear all cached scores (e.g. on reset-to-seed). */
export function clearProgress(): void {
  for (const key of Object.keys(scoreCache)) delete scoreCache[key]
  for (const key of Object.keys(notesCache)) delete notesCache[key]
}

/**
 * Return the progress percent (0–100) for a notebook or page id.
 *
 * Reads from the backend-populated cache; returns `DEFAULT_PROGRESS` for ids
 * that have not been evaluated yet.
 */
export function getProgress(id: string): number {
  return scoreCache[id] ?? DEFAULT_PROGRESS
}

/**
 * Return the LLM's understanding notes for an id, or an empty string if the id
 * has not been evaluated (or the backend returned no notes).
 */
export function getUnderstandingNotes(id: string): string {
  return notesCache[id] ?? ''
}

/**
 * Progress model for notebooks and pages.
 *
 * ─────────────────────────────────────────────────────────────────────────
 * BACKEND SEAM
 * ─────────────────────────────────────────────────────────────────────────
 * Progress values are now provided by the Spring Boot backend, which asks an
 * LLM (or a deterministic offline heuristic) to grade how well each notebook /
 * page topic appears to be understood — following the Feynman technique.
 *
 * The backend result is cached in-module via `setProgress` / `setProgresses`
 * (populated by `useProgressStore`), so the widely-used `getProgress(id)`
 * accessor stays synchronous for templates.
 *
 * Color thresholds are centralized here so they can be made user-customizable
 * later without touching the components.
 */

import { ref } from 'vue'

export interface ProgressThresholds {
  /** Below this percent → "danger" (red). */
  danger: number
  /** Below this percent → "warn" (yellow); at/above → "good" (green). */
  warn: number
}

/** Default thresholds: red < 33, yellow < 75, green ≥ 75. */
export const DEFAULT_THRESHOLDS: ProgressThresholds = {
  danger: 33,
  warn: 75
}

export type ProgressLevel = 'danger' | 'warn' | 'good'

/**
 * Reactive counter bumped whenever cached scores/feedback change. Components can
 * read it inside a `computed` to establish a reactive dependency on the
 * otherwise plain (non-reactive) caches, so they refresh after an evaluation.
 */
export const scoreVersion = ref(0)

/**
 * Map a percent value to a color level using the given thresholds.
 */
export function progressLevel(
  value: number,
  thresholds: ProgressThresholds = DEFAULT_THRESHOLDS
): ProgressLevel {
  if (value < thresholds.danger) return 'danger'
  if (value < thresholds.warn) return 'warn'
  return 'good'
}

/**
 * In-memory cache of backend-evaluated scores, keyed by notebook / page id.
 * Populated by `useProgressStore.evaluate()` after calling the backend.
 */
const scoreCache: Record<string, number> = {}

/**
 * In-memory cache of the LLM's short "understanding notes" per id, shown as a
 * tooltip on the progress badge so users can see WHY a topic scored as it did.
 */
const notesCache: Record<string, string> = {}

/**
 * In-memory cache of the LLM's longer, actionable "feedback" per id, shown as a
 * distinguishable callout inside the evaluated notebook.
 */
const feedbackCache: Record<string, string> = {}

/**
 * Fallback percent for ids the backend has not evaluated yet (e.g. a newly
 * created notebook/page, or before the first evaluation completes).
 */
export const DEFAULT_PROGRESS = 0

/** Clamp a raw value into the valid 0–100 progress range. */
function clamp(value: number): number {
  if (Number.isNaN(value)) return DEFAULT_PROGRESS
  return Math.max(0, Math.min(100, Math.round(value)))
}

/** Store a single backend-evaluated score. */
export function setProgress(id: string, value: number): void {
  scoreCache[id] = clamp(value)
}

/** Bulk-store backend-evaluated scores (id → percent). */
export function setProgresses(scores: Record<string, number>): void {
  for (const [id, value] of Object.entries(scores)) {
    scoreCache[id] = clamp(value)
  }
}

/**
 * Merge backend evaluation results into the progress cache.
 *
 * Accepts the `{ score, understandingNotes }` shape returned by the backend
 * (see `evaluationApi.ts`), so callers can pass `pageScores` / `notebookScores`
 * directly.
 */
export function setLiveScores(
  scores: Record<string, { score: number; understandingNotes?: string; feedback?: string }>
): void {
  for (const [id, entry] of Object.entries(scores)) {
    if (entry && typeof entry.score === 'number') {
      scoreCache[id] = clamp(entry.score)
      if (entry.understandingNotes) {
        notesCache[id] = entry.understandingNotes
      }
      if (entry.feedback) {
        feedbackCache[id] = entry.feedback
      }
    }
  }
  scoreVersion.value++
}

/** Clear all cached scores (e.g. on reset-to-seed). */
export function clearProgress(): void {
  for (const key of Object.keys(scoreCache)) delete scoreCache[key]
  for (const key of Object.keys(notesCache)) delete notesCache[key]
  for (const key of Object.keys(feedbackCache)) delete feedbackCache[key]
  scoreVersion.value++
}

/**
 * Return the progress percent (0–100) for a notebook or page id.
 *
 * Reads from the backend-populated cache; returns `DEFAULT_PROGRESS` for ids
 * that have not been evaluated yet.
 */
export function getProgress(id: string): number {
  return scoreCache[id] ?? DEFAULT_PROGRESS
}

/**
 * Return the LLM's understanding notes for an id, or an empty string if the id
 * has not been evaluated (or the backend returned no notes).
 */
export function getUnderstandingNotes(id: string): string {
  return notesCache[id] ?? ''
}

/**
 * Return the LLM's longer feedback paragraph for an id, or an empty string if
 * the id has not been evaluated (or the backend returned no feedback).
 */
export function getFeedback(id: string): string {
  return feedbackCache[id] ?? ''
}
